17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
34	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        List<String> missingFields = new ArrayList<>();
107	        if (isBlank(ownerFieldsDto.getFirstName())) {
108	            missingFields.add("firstName");
109	        }
110	        if (isBlank(ownerFieldsDto.getLastName())) {
111	            missingFields.add("lastName");
112	        }
113	        if (isBlank(ownerFieldsDto.getAddress())) {
114	            missingFields.add("address");
115	        }
116	        if (isBlank(ownerFieldsDto.getCity())) {
117	            missingFields.add("city");
118	        }
119	        if (isBlank(ownerFieldsDto.getTelephone())) {
120	            missingFields.add("telephone");
121	        }
122	        if (!missingFields.isEmpty()) {
123	            throw new MissingOwnerFieldsException(missingFields);
124	        }
125	        String telephone = ownerFieldsDto.getTelephone().replaceAll("\\D", "");
126	        if (telephone.length() != 10) {
127	            throw new InvalidTelephoneException(
128	                "telephone must contain exactly 10 digits after removing non-digit characters");
129	        }
130	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
131	            .anyMatch(existing -> telephone.equals(normalizeTelephone(existing.getTelephone())));
132	        if (telephoneInUse) {
133	            throw new DuplicateTelephoneException(
134	                "an owner with the same normalized telephone already exists");
135	        }
136	        ownerFieldsDto.setTelephone(telephone);
137	        HttpHeaders headers = new HttpHeaders();
138	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
139	        this.clinicService.saveOwner(owner);
140	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
141	        headers.setLocation(UriComponentsBuilder.newInstance()
142	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
143	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
149	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
150	        if (currentOwner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        currentOwner.setAddress(ownerFieldsDto.getAddress());
154	        currentOwner.setCity(ownerFieldsDto.getCity());
155	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
156	        currentOwner.setLastName(ownerFieldsDto.getLastName());
157	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
158	        this.clinicService.saveOwner(currentOwner);
159	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Transactional
164	    @Override
165	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
166	        Owner owner = this.clinicService.findOwnerById(ownerId);
167	        if (owner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        this.clinicService.deleteOwner(owner);
171	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
177	        Owner owner = this.clinicService.findOwnerById(ownerId);
178	        if (owner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        HttpHeaders headers = new HttpHeaders();
182	        Pet pet = petMapper.toPet(petFieldsDto);
183	        owner.setId(ownerId);
184	        pet.setOwner(owner);
185	        pet.getType().setName(null);
186	        this.clinicService.savePet(pet);
187	        PetDto petDto = petMapper.toPetDto(pet);
188	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
189	            .buildAndExpand(pet.getId()).toUri());
190	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
196	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
197	        if (currentOwner != null) {
198	            Pet currentPet = this.clinicService.findPetById(petId);
199	            if (currentPet != null) {
200	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
201	                currentPet.setName(petFieldsDto.getName());
202	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
203	                this.clinicService.savePet(currentPet);
204	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
205	            }
206	        }
207	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
213	        HttpHeaders headers = new HttpHeaders();
214	        Visit visit = visitMapper.toVisit(visitFieldsDto);
215	        Pet pet = new Pet();
216	        pet.setId(petId);
217	        visit.setPet(pet);
218	        this.clinicService.saveVisit(visit);
219	        VisitDto visitDto = visitMapper.toVisitDto(visit);
220	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
221	            .buildAndExpand(visit.getId()).toUri());
222	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
223	    }
224	
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
229	        Owner owner = this.clinicService.findOwnerById(ownerId);
230	        if (owner != null) {
231	            Pet pet = owner.getPet(petId);
232	            if (pet != null) {
233	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
234	            }
235	        }
236	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	    }
238	
239	    private static boolean isBlank(String value) {
240	        return value == null || value.isBlank();
241	    }
242	
243	    private static String normalizeTelephone(String telephone) {
244	        return telephone == null ? null : telephone.replaceAll("\\D", "");
245	    }
246	}
